describe('Notification Click Navigation', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should navigate to relevant content when clicking a notification', () => {
    // Verify notification is visible
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'New article published');

    // Click the notification
    cy.get('[data-testid="notification-item"]').click();

    // Verify navigation occurred
    cy.url().should('include', '/articles');

    // Verify we are on the correct page
    cy.get('[data-testid="article-title"]').should('be.visible');
    cy.get('[data-testid="article-title"]').should('contain', 'New article published');

    // Verify content is displayed
    cy.get('[data-testid="article-content"]').should('be.visible');
    cy.get('[data-testid="article-content"]').should('contain', 'This is the article content');
  });

  it('should handle edge case when notification is empty or not clickable', () => {
    // Verify notification is empty
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('contain', 'No new notifications');

    // Attempt to click an empty notification
    cy.get('[data-testid="notification-item"]').click();

    // Verify navigation did not occur
    cy.url().should('not.include', '/articles');

    // Verify user is still on notifications page
    cy.url().should('include', '/notifications');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'No new notifications');
  });
});
